// Some portions generated by Claude
// Some portions generated by Codex
/**
 * Fans: the pendant children of a card arranged around it on a box-shaped ring.
 *
 * An inner rectangle is centred on the anchor card, at least one arrow length (L) wider than the card on every side.
 * Children ("units": a child card with everything hanging below it, drawn as one rigid shape) stand outside the
 * rectangle with their inner edge on it: stacked in columns on its left and right sides and side by side on its top
 * and bottom sides, in the children's order clockwise from the top of the right side. Every arrow from the anchor to a
 * child then runs inside the rectangle and ends on the side of the child that faces the anchor, so arrows of a fan
 * never cross each other or a card, whatever the cards' widths. Cards are about 4.8 times wider than tall, so columns
 * hold most children cheaply and rows only a few; the rectangle's size is searched for the smallest drawing near the
 * wanted aspect ratio.
 *
 * A child with children of its own fans them on the half of its own rectangle that faces away from its anchor, so a
 * branch grows outward like a mind map. Shapes are computed bottom-up, once per outward side.
 */
import {segmentHitsBox} from './graph-layout-stress.ts';
import {BoundsTree} from './spatial-grid.ts';

export type Extents = {left: number; right: number; top: number; bottom: number};
/** Outward side: 0 = right, 1 = below, 2 = left, 3 = above. */
export type Side = 0 | 1 | 2 | 3;

export type UnitShape = {
  /** The whole unit around its own card's centre. */
  extents: Extents;
  /** Every card of the unit (its own card at 0, 0) relative to its card's centre. */
  offsets: Map<number, {x: number; y: number}>;
};

export type FanSpacing = {edgeLength: number; clearX: number; clearY: number; aspectRatio: number};

/**
 * Obstacles around an anchor, in the anchor's coordinates; `directions` are the anchor's own links (radians), which a
 * unit keeps `SPOKE_CLEARANCE` away from, so a fan never hugs a link to the rest of the drawing.
 */
export type FanObstacles = {boxes: Extents[]; segments: Array<[number, number, number, number]>; directions?: number[];
  /** Areas units keep out of while arrows may cross them (the inside of another fan's ring). */
  areas?: Extents[];
  /** Arrows may pass behind obstacle cards (a relaxed retry when no ring keeps every arrow clear). */
  shadows?: boolean};

/** Angle a fan's units keep from the anchor's other links. */
export const SPOKE_CLEARANCE = (32 * Math.PI) / 180;

export type FanPlacement = {card: number; side: Side; x: number; y: number; shape: UnitShape};

/** A fan: its units, its extent around the anchor, and the inner rectangle of its ring (`ring`) or ellipse. */
export type Fan = {placements: FanPlacement[]; extents: Extents; inner: {hx: number; hy: number}; ring?: boolean};

type FanRequest = {
  /** Half size of the anchor card. */
  halfWidth: number;
  halfHeight: number;
  units: number[];
  shape: (card: number, side: Side) => UnitShape;
  spacing: FanSpacing;
  /** Part of the ring the children may use, centred on this side's middle and spanning `span` of the perimeter. */
  facing?: Side;
  span?: number;
  /** Spread the children over the whole ring (a root) instead of packing them around `facing`. */
  spread?: boolean;
  /** Exact direction (radians, y down) the fan faces, when known; a small fan of leaves is centred on it. */
  direction?: number;
  obstacles?: FanObstacles;
};

type FanObstacleGeometry = {boxes?: FanBoxIndex; areas?: FanBoxIndex; segments?: FanSegmentIndex};
type FanSearch = FanRequest & {obstacleGeometry?: FanObstacleGeometry};

function validBounds(left: number, top: number, right: number, bottom: number) {
  return Number.isFinite(left) && Number.isFinite(top) && Number.isFinite(right) && Number.isFinite(bottom) &&
    left <= right && top <= bottom;
}

/** Static obstacle geometry shared by the searches and relaxed retries of one fan placement. */
class FanBoxIndex {
  private readonly tree: BoundsTree | null = null;
  private readonly count: number;
  private readonly boxes: readonly Extents[];
  private readonly clearX: number;
  private readonly clearY: number;
  private arrowPadX: number | null | undefined;
  private arrowPadY = 1;
  private boxWitness = 0;
  private arrowWitness = 0;

  constructor(boxes: readonly Extents[], clearX: number, clearY: number) {
    this.boxes = boxes; this.clearX = clearX; this.clearY = clearY;
    this.count = boxes.length;
    if (!this.count || !Number.isFinite(clearX) || !Number.isFinite(clearY) || clearX < 0 || clearY < 0) return;
    const minX = new Float64Array(this.count), minY = new Float64Array(this.count);
    const maxX = new Float64Array(this.count), maxY = new Float64Array(this.count);
    for (let i = 0; i < this.count; i++) {
      const box = boxes[i];
      if (!validBounds(box.left, box.top, box.right, box.bottom)) return;
      minX[i] = box.left; minY[i] = box.top;
      // Match the additions in boxesTouch exactly, instead of moving a clearance across an inequality.
      maxX[i] = box.right + clearX; maxY[i] = box.bottom + clearY;
      if (!validBounds(minX[i], minY[i], maxX[i], maxY[i])) return;
    }
    this.tree = new BoundsTree(minX, minY, maxX, maxY);
  }

  touches(box: Extents, boxes: readonly Extents[], spacing: FanSpacing) {
    if (!boxes.length) return false;
    const {clearX, clearY} = spacing;
    const right = box.right + clearX, bottom = box.bottom + clearY;
    if (this.tree && boxes === this.boxes && boxes.length === this.count &&
        Object.is(clearX, this.clearX) && Object.is(clearY, this.clearY) &&
        validBounds(box.left, box.top, box.right, box.bottom) && validBounds(box.left, box.top, right, bottom)) {
      // Inclusive bounds may include a tangent; the original strict, pure predicate decides it. Spatial visit
      // order affects only this boolean, never the solver's placement/tie order. Keep the cheap box-zero hit.
      if (boxesTouch(box, boxes[0], clearX, clearY)) { this.boxWitness = 0; return true; }
      // Ring trials move nearby: a previous blocker is useful only after the exact predicate certifies it again.
      const witness = this.boxWitness;
      if (witness !== 0 && boxesTouch(box, boxes[witness], clearX, clearY)) return true;
      return this.tree.some(box.left, box.top, right, bottom, i => {
        if (i === 0 || i === witness || !boxesTouch(box, boxes[i], clearX, clearY)) return false;
        this.boxWitness = i;
        return true;
      });
    } else {
      // The exported solver historically accepts unusual coordinates/extents/spacing. Preserve its scans rather
      // than adding validation, truncating coordinates or making an invalid spatial query look empty.
      for (const obstacle of boxes) if (boxesTouch(box, obstacle, clearX, clearY)) return true;
    }
    return false;
  }

  private prepareArrowPadding() {
    this.arrowPadX = null;
    let padX = 1, padY = 1;
    for (const box of this.boxes) {
      const left = box.left - 10, top = box.top - 10, right = box.right + 10, bottom = box.bottom + 10;
      if (!validBounds(left, top, right, bottom)) return;
      padX = Math.max(padX, clippingMargin(left, right));
      padY = Math.max(padY, clippingMargin(top, bottom));
    }
    this.arrowPadX = padX; this.arrowPadY = padY;
  }

  /** Whether the arrow from the anchor to (x, y) hits an obstacle card. */
  hitsArrow(x: number, y: number, boxes: readonly Extents[]) {
    if (!boxes.length) return false;
    let witness = 0;
    if (this.arrowWitness !== 0 && this.tree && boxes === this.boxes && boxes.length === this.count &&
        Number.isFinite(x) && Number.isFinite(y)) {
      witness = this.arrowWitness;
      const box = boxes[witness];
      // Revalidate the last exact blocker before trying box zero again. A true certificate already proves this
      // pure boolean query; a miss still reacquires zero or visits every other untested obstacle below.
      if (segmentHitsBox(0, 0, x, y, box.left - 10, box.top - 10, box.right + 10, box.bottom + 10)) return true;
    }
    const first = boxes[0];
    if (segmentHitsBox(0, 0, x, y, first.left - 10, first.top - 10, first.right + 10, first.bottom + 10)) {
      this.arrowWitness = 0;
      return true;
    }
    if (boxes.length === 1) return false;
    if (this.tree && boxes === this.boxes && boxes.length === this.count && Number.isFinite(x) && Number.isFinite(y)) {
      if (this.arrowPadX === undefined) this.prepareArrowPadding();
      if (this.arrowPadX !== null && this.arrowPadX !== undefined) {
        const padX = clippingMargin(0, x) + this.arrowPadX, padY = clippingMargin(0, y) + this.arrowPadY;
        const left = Math.min(0, x) - 10 - padX, top = Math.min(0, y) - 10 - padY;
        const right = Math.max(0, x) + 10 + padX, bottom = Math.max(0, y) + 10 + padY;
        if (validBounds(left, top, right, bottom)) {
          // The unit tree already contains every raw card box (its clearances are nonnegative). Expanding the
          // arrow query by ten and both operand-scale margins conservatively covers the original padded cards.
          // The exact clip is pure, so spatial visit order changes neither this boolean nor solver tie ordering.
          return this.tree.some(left, top, right, bottom, i => {
            if (i === 0 || i === witness) return false;
            const box = boxes[i];
            if (!segmentHitsBox(0, 0, x, y, box.left - 10, box.top - 10, box.right + 10, box.bottom + 10)) return false;
            this.arrowWitness = i;
            return true;
          });
        }
      }
    }
    for (let i = 1; i < boxes.length; i++) {
      if (i === witness) continue;
      const box = boxes[i];
      if (segmentHitsBox(0, 0, x, y, box.left - 10, box.top - 10, box.right + 10, box.bottom + 10)) return true;
    }
    return false;
  }
}

/**
 * Bounds for the unchanged Liang–Barsky clip. Its endpoint subtraction and division can round a parameter just
 * outside [0, 1] onto an endpoint. With u = EPSILON/2, the three finite subtraction/division roundings have
 * error gamma3 = 3u/(1-3u). A delta is at most twice its operand scale S, giving about 6u*S endpoint error;
 * eight epsilons provide 16u*S on each independently padded segment/query axis, including bound arithmetic.
 * The established one-pixel floor also covers underflow/near-parallel drawing scales; the original parallel clip
 * is unchanged. Nonfinite delta/padded arithmetic and inverted queries use the exact scan instead.
 */
function clippingMargin(a: number, b: number) {
  return Math.max(1, 8 * Number.EPSILON * Math.max(Math.abs(a), Math.abs(b)));
}

/** Static segments shared only within one fan placement, including its relaxed retries. */
class FanSegmentIndex {
  private tree: BoundsTree | null | undefined;
  private crossingWitness = 0;
  private unitWitness = 0;
  private readonly segments: readonly [number, number, number, number][];
  private readonly count: number;

  constructor(segments: readonly [number, number, number, number][]) {
    this.segments = segments; this.count = segments.length;
  }

  private prepare() {
    this.tree = null;
    const minX = new Float64Array(this.count), minY = new Float64Array(this.count);
    const maxX = new Float64Array(this.count), maxY = new Float64Array(this.count);
    for (let i = 0; i < this.count; i++) {
      const [x0, y0, x1, y1] = this.segments[i];
      if (!Number.isFinite(x1 - x0) || !Number.isFinite(y1 - y0)) return;
      const padX = clippingMargin(x0, x1), padY = clippingMargin(y0, y1);
      minX[i] = Math.min(x0, x1) - padX; minY[i] = Math.min(y0, y1) - padY;
      maxX[i] = Math.max(x0, x1) + padX; maxY[i] = Math.max(y0, y1) + padY;
      if (!validBounds(minX[i], minY[i], maxX[i], maxY[i])) return;
    }
    this.tree = new BoundsTree(minX, minY, maxX, maxY);
  }

  hits(minX: number, minY: number, maxX: number, maxY: number,
    segments: readonly [number, number, number, number][]) {
    if (!segments.length) return false;
    const [x0, y0, x1, y1] = segments[0];
    // Preserve the original first-hit shortcut, even for unusual coordinates, before any index setup or query.
    if (segmentHitsBox(x0, y0, x1, y1, minX, minY, maxX, maxY)) { this.unitWitness = 0; return true; }
    if (segments.length === 1) return false;
    const reusable = segments === this.segments && segments.length === this.count;
    const witness = reusable ? this.unitWitness : 0;
    // Cache only an ID: every new box must pass the original exact clip before a previous hit can be reused.
    if (witness !== 0) {
      const [ax, ay, bx, by] = segments[witness];
      if (segmentHitsBox(ax, ay, bx, by, minX, minY, maxX, maxY)) return true;
    }
    const padX = clippingMargin(minX, maxX), padY = clippingMargin(minY, maxY);
    const left = minX - padX, top = minY - padY, right = maxX + padX, bottom = maxY + padY;
    if (reusable && validBounds(minX, minY, maxX, maxY) && validBounds(left, top, right, bottom)) {
      if (this.tree === undefined) this.prepare();
      if (this.tree) {
        // Inclusive bounds keep tangencies. Clipping is a pure boolean predicate on immutable numbers, so its
        // internal candidate order cannot affect this decision or the solver's placement/tie ordering.
        return this.tree.some(left, top, right, bottom, i => {
          if (i === 0 || i === witness) return false;
          const [ax, ay, bx, by] = segments[i];
          if (!segmentHitsBox(ax, ay, bx, by, minX, minY, maxX, maxY)) return false;
          this.unitWitness = i;
          return true;
        });
      }
    }
    // No validation or new coordinate limits: scan every untested ID for unsafe geometry as well.
    for (let i = 1; i < witness; i++) {
      const [ax, ay, bx, by] = segments[i];
      if (segmentHitsBox(ax, ay, bx, by, minX, minY, maxX, maxY)) {
        if (reusable) this.unitWitness = i;
        return true;
      }
    }
    for (let i = witness + 1; i < segments.length; i++) {
      const [ax, ay, bx, by] = segments[i];
      if (segmentHitsBox(ax, ay, bx, by, minX, minY, maxX, maxY)) {
        if (reusable) this.unitWitness = i;
        return true;
      }
    }
    return false;
  }

  /** Revalidate a previous crossing witness, then scan every remaining segment if it no longer crosses. */
  crossesArrow(x: number, y: number, segments: readonly [number, number, number, number][]) {
    if (!segments.length) return false;
    const [x0, y0, x1, y1] = segments[0];
    if (segmentsCross(0, 0, x, y, x0, y0, x1, y1)) { this.crossingWitness = 0; return true; }
    const reusable = segments === this.segments && segments.length === this.count;
    const witness = reusable ? this.crossingWitness : 0;
    if (witness !== 0) {
      const [ax, ay, bx, by] = segments[witness];
      if (segmentsCross(0, 0, x, y, ax, ay, bx, by)) return true;
    }
    // The predicate is pure; a freshly certified hit is sufficient. On a miss, test all other IDs exactly once,
    // in two ranges so sparse/no-witness scans need no extra per-segment skip branch or geometric assumption.
    for (let i = 1; i < witness; i++) {
      const [ax, ay, bx, by] = segments[i];
      if (segmentsCross(0, 0, x, y, ax, ay, bx, by)) {
        if (reusable) this.crossingWitness = i;
        return true;
      }
    }
    for (let i = witness + 1; i < segments.length; i++) {
      const [ax, ay, bx, by] = segments[i];
      if (segmentsCross(0, 0, x, y, ax, ay, bx, by)) {
        if (reusable) this.crossingWitness = i;
        return true;
      }
    }
    return false;
  }
}

/** Fans of at most this many leaves are drawn on an ellipse around the anchor, like a small star. */
export const ELLIPSE_FAN_MAX = 8;
/** Widest arc of a small fan that faces away from the anchor's other links. */
const ELLIPSE_FACING_SPAN = (200 * Math.PI) / 180;
/** Widest ratio between the ellipse's axes: leaves stay at nearly even distances from their anchor. */
const ELLIPSE_RATIO = 1.5;
/** How far a small fan's ellipse may grow to clear obstacles before the ring walk takes over. */
const ELLIPSE_OBSTACLE_GROWTH = 1.7;

/** Fans of at least this many leaves fill concentric rings (`ringsFan`) instead of one ring. */
export const RINGS_FAN_MIN = 40;
/** Room between two rings, in clearances: what is left beside a card is a lane for the arrows to the rings outside. */
const RING_LANE = 1.5;
/** Rings a big fan may use before it gives up on the obstacles around it. */
const RINGS_MAX = 200;

const ALONG_STEP = 8;

/** Point of the ring at perimeter coordinate t, clockwise from the top of the right side: [side, offset on side]. */
function locate(t: number, hx: number, hy: number): [Side, number] {
  const perimeter = 4 * hx + 4 * hy;
  let r = ((t % perimeter) + perimeter) % perimeter;
  if (r < 2 * hy) return [0, r];
  r -= 2 * hy;
  if (r < 2 * hx) return [1, r];
  r -= 2 * hx;
  if (r < 2 * hy) return [2, r];
  return [3, r - 2 * hy];
}

/** Perimeter coordinate where side `side` starts. */
function sideStart(side: Side, hx: number, hy: number) {
  return side === 0 ? 0 : side === 1 ? 2 * hy : side === 2 ? 2 * hy + 2 * hx : 4 * hy + 2 * hx;
}

const sideLength = (side: Side, hx: number, hy: number) => (side % 2 === 0 ? 2 * hy : 2 * hx);
const alongExtent = (side: Side, e: Extents) => (side % 2 === 0 ? e.top + e.bottom : e.left + e.right);

/** Centre of a unit's card whose part of the ring starts at offset `s` of `side`. */
function cardCentre(side: Side, s: number, e: Extents, hx: number, hy: number) {
  switch (side) {
    case 0: return {x: hx + e.left, y: -hy + s + e.top};
    case 1: return {x: hx - s - e.right, y: hy + e.top};
    case 2: return {x: -hx - e.right, y: hy - s - e.bottom};
    default: return {x: -hx + s + e.left, y: -hy - e.bottom};
  }
}

/** Middle of the side of a unit's card that faces the anchor: where its arrow ends. */
function innerPort(side: Side, x: number, y: number, cardHalfWidth: number, cardHalfHeight: number) {
  switch (side) {
    case 0: return {x: x - cardHalfWidth, y};
    case 1: return {x, y: y - cardHalfHeight};
    case 2: return {x: x + cardHalfWidth, y};
    default: return {x, y: y + cardHalfHeight};
  }
}

function boxesTouch(a: Extents, b: Extents, clearX: number, clearY: number) {
  // Extents here are absolute bounds stored as left = minX, right = maxX, top = minY, bottom = maxY.
  return a.left < b.right + clearX && b.left < a.right + clearX && a.top < b.bottom + clearY && b.top < a.bottom + clearY;
}

/**
 * Walks the ring from perimeter coordinate `start`, placing every unit in order where it fits on one side, is clear of
 * the obstacles and keeps `gapScale` times the clearance to the previous unit. Fails when the units do not fit within
 * `limit` of the perimeter.
 */
function walk(request: FanSearch, hx: number, hy: number, start: number, limit: number,
  gapScale: number): FanPlacement[] | null {
  const {units, shape, spacing, obstacles, obstacleGeometry} = request;
  const placements: FanPlacement[] = [];
  let t = start;
  const end = start + limit + 1e-6;
  for (const unit of units) {
    let placed = false;
    for (let guard = 0; guard < 4000 && !placed; guard++) {
      if (t > end) return null;
      const [side, s] = locate(t, hx, hy);
      const length = sideLength(side, hx, hy);
      const margin = side % 2 === 0 ? spacing.clearY : 0;
      if (s < margin - 1e-6) { t += margin - s; continue; }
      const unitShape = shape(unit, side);
      const along = alongExtent(side, unitShape.extents);
      if (s + along > length - margin + 1e-6) {
        // Next side.
        const next = ((side + 1) % 4) as Side;
        const target = sideStart(next, hx, hy) + (next % 2 === 0 ? spacing.clearY : 0);
        const base = t - s - sideStart(side, hx, hy);
        t = base + (next === 0 ? 4 * hx + 4 * hy : 0) + target;
        continue;
      }
      if (t + along > end) return null;
      const centre = cardCentre(side, s, unitShape.extents, hx, hy);
      if (obstacles && blocked(centre, side, unitShape, obstacles, spacing, obstacleGeometry)) {
        t += ALONG_STEP; continue;
      }
      // Units of earlier sides may reach around a corner of a crowded ring; keep the clearance to every placed unit.
      const box = absolute(centre, unitShape.extents);
      if (placements.some(p => boxesTouch(box, absolute(p, p.shape.extents), spacing.clearX - 0.01, spacing.clearY - 0.01))) { t += ALONG_STEP; continue; }
      placements.push({card: unit, side, x: centre.x, y: centre.y, shape: unitShape});
      t += along + (side % 2 === 0 ? spacing.clearY : spacing.clearX) * gapScale;
      placed = true;
    }
    if (!placed) return null;
  }
  return placements;
}

function absolute(centre: {x: number; y: number}, e: Extents): Extents {
  return {left: centre.x - e.left, right: centre.x + e.right, top: centre.y - e.top, bottom: centre.y + e.bottom};
}

/** Whether a unit at `centre` on `side` meets an obstacle, or its arrow from the anchor's centre does. */
function blocked(centre: {x: number; y: number}, side: Side, unit: UnitShape, obstacles: FanObstacles,
  spacing: FanSpacing, geometry?: FanObstacleGeometry) {
  const box = absolute(centre, unit.extents);
  if (obstacles.boxes.length) {
    if (geometry?.boxes) {
      if (geometry.boxes.touches(box, obstacles.boxes, spacing)) return true;
    } else {
      for (const o of obstacles.boxes) if (boxesTouch(box, o, spacing.clearX, spacing.clearY)) return true;
    }
  }
  if (obstacles.areas?.length) {
    if (geometry?.areas) {
      if (geometry.areas.touches(box, obstacles.areas, spacing)) return true;
    } else {
      for (const o of obstacles.areas) if (boxesTouch(box, o, spacing.clearX, spacing.clearY)) return true;
    }
  }
  const card = cardHalf(unit);
  const port = innerPort(side, centre.x, centre.y, card.w, card.h);
  if (geometry?.segments) {
    if (geometry.segments.hits(box.left - 10, box.top - 10, box.right + 10, box.bottom + 10,
      obstacles.segments)) return true;
  } else {
    for (const [x0, y0, x1, y1] of obstacles.segments) {
      if (segmentHitsBox(x0, y0, x1, y1, box.left - 10, box.top - 10, box.right + 10, box.bottom + 10)) return true;
    }
  }
  if (obstacles.shadows) return false;
  if (obstacles.boxes.length) {
    if (geometry?.boxes) {
      if (geometry.boxes.hitsArrow(port.x, port.y, obstacles.boxes)) return true;
    } else {
      for (const o of obstacles.boxes) if (segmentHitsBox(0, 0, port.x, port.y,
        o.left - 10, o.top - 10, o.right + 10, o.bottom + 10)) return true;
    }
  }
  // The unit's own arrow must not cross the anchor's other links or the links around it.
  if (geometry?.segments) {
    if (geometry.segments.crossesArrow(port.x, port.y, obstacles.segments)) return true;
  } else {
    for (const [x0, y0, x1, y1] of obstacles.segments) {
      if (segmentsCross(0, 0, port.x, port.y, x0, y0, x1, y1)) return true;
    }
  }
  if (obstacles.directions?.length) {
    // At most half the circle is kept clear, so a big fan around a well-linked card still finds room.
    const clearance = Math.min(SPOKE_CLEARANCE, Math.PI / (2 * obstacles.directions.length));
    const angle = Math.atan2(centre.y, centre.x);
    for (const direction of obstacles.directions) if (Math.abs(Math.atan2(Math.sin(angle - direction), Math.cos(angle - direction))) < clearance) return true;
  }
  return false;
}

function segmentsCross(ax: number, ay: number, bx: number, by: number, cx: number, cy: number, dx: number, dy: number) {
  const d1 = (bx - ax) * (cy - ay) - (by - ay) * (cx - ax), d2 = (bx - ax) * (dy - ay) - (by - ay) * (dx - ax);
  // The second orientation pair cannot change a failed first test. Keep every retained arithmetic operation exact.
  if (!(d1 * d2 < -1e-9)) return false;
  const d3 = (dx - cx) * (ay - cy) - (dy - cy) * (ax - cx), d4 = (dx - cx) * (by - cy) - (dy - cy) * (bx - cx);
  return d3 * d4 < -1e-9;
}

/** Half size of a unit's own card, recorded under the key −1 of its offsets. */
function cardHalf(unit: UnitShape) {
  const half = unit.offsets.get(-1);
  return half ? {w: half.x, h: half.y} : {w: unit.extents.left, h: unit.extents.top};
}

/** Bounding extents (around the anchor's centre) of the anchor card and all placed units. */
function fanExtents(request: FanRequest, placements: FanPlacement[]): Extents {
  let left = request.halfWidth, right = request.halfWidth, top = request.halfHeight, bottom = request.halfHeight;
  for (const p of placements) {
    left = Math.max(left, p.shape.extents.left - p.x);
    right = Math.max(right, p.x + p.shape.extents.right);
    top = Math.max(top, p.shape.extents.top - p.y);
    bottom = Math.max(bottom, p.y + p.shape.extents.bottom);
  }
  return {left, right, top, bottom};
}

function score(e: Extents, aspectRatio: number) {
  const width = e.left + e.right, height = e.top + e.bottom;
  const skew = Math.log((width / Math.max(1, height)) / aspectRatio);
  return width * height * (1 + skew * skew);
}

/**
 * Places the units around the anchor: searches the inner rectangle (its half height from the smallest allowed up to a
 * single column holding everything, its half width the smallest that fits) for the drawing with the best score.
 */
export function placeFan(request: FanRequest): Fan {
  return placePreparedFan(request);
}

function placePreparedFan(request: FanSearch): Fan {
  const {units, spacing} = request;
  const small = ellipseFan(request);
  if (small) return small;
  if (!units.length) {
    const e = {left: request.halfWidth, right: request.halfWidth, top: request.halfHeight, bottom: request.halfHeight};
    return {placements: [], extents: e, inner: {hx: request.halfWidth + spacing.edgeLength, hy: request.halfHeight + spacing.edgeLength}};
  }
  // Empty/successful ellipse fans need no index, and obstacle-free child fans need no request copy. The ring search
  // reuses static geometry across its many trials; recursive retries still try the ellipse first, exactly once.
  const {obstacles} = request;
  if (obstacles && !request.obstacleGeometry &&
      (obstacles.boxes.length || obstacles.areas?.length || obstacles.segments.length > 1)) {
    // Callers finish these arrays before placing a fan; retries relax only directions/shadows. Never cache them
    // beyond this public call, so later caller mutation cannot leave a stale index.
    request = {...request, obstacleGeometry: {
      boxes: obstacles.boxes.length ? new FanBoxIndex(obstacles.boxes, spacing.clearX, spacing.clearY) : undefined,
      areas: obstacles.areas?.length ? new FanBoxIndex(obstacles.areas, spacing.clearX, spacing.clearY) : undefined,
      segments: obstacles.segments.length > 1 ? new FanSegmentIndex(obstacles.segments) : undefined,
    }};
  }
  const big = ringsFan(request);
  if (big) return big;
  const hxMin = request.halfWidth + spacing.edgeLength, hyMin = request.halfHeight + spacing.edgeLength * 0.7;
  // Upper bounds: everything in one column, everything in one row.
  let column = 0, row = 0;
  for (const unit of units) {
    const e = request.shape(unit, 0).extents, f = request.shape(unit, 3).extents;
    column += e.top + e.bottom + spacing.clearY;
    row += f.left + f.right + spacing.clearX;
  }
  const hyMax = Math.max(hyMin, column / 2 + spacing.clearY), hxMax = Math.max(hxMin, row / 2 + spacing.clearX);
  const span = request.span ?? 1;
  let best: {placements: FanPlacement[]; extents: Extents; hx: number; hy: number; value: number} | null = null;
  const steps = Math.min(40, Math.max(6, Math.ceil((hyMax - hyMin) / 20)));
  for (let i = 0; i <= steps; i++) {
    const hy = hyMin + (hyMax - hyMin) * i / steps;
    const attempt = (hx: number) => arrange(request, hx, hy, span);
    let low = hxMin, high = hxMax;
    let found = attempt(high);
    if (!found) {
      // Obstacles can block even the widest ring; grow it until the units fit.
      for (let grow = 0; grow < 8 && !found; grow++) { high *= 1.4; found = attempt(high); }
      if (!found) continue;
    }
    for (let iteration = 0; iteration < 14 && high - low > 2; iteration++) {
      const middle = (low + high) / 2, placed = attempt(middle);
      if (placed) { high = middle; found = placed; } else low = middle;
    }
    const extents = fanExtents(request, found);
    const value = score(extents, spacing.aspectRatio);
    if (!best || value < best.value - 1e-6) best = {placements: found, extents, hx: high, hy, value};
  }
  if (!best) {
    // The obstacles leave no room on any ring: relax them step by step (the angle kept from the anchor's links, then
    // arrows passing behind cards, then everything); the polish moves what remains aside.
    const o = request.obstacles;
    if (o?.directions?.length) return placePreparedFan({...request, obstacles: {...o, directions: undefined}});
    if (o && !o.shadows) return placePreparedFan({...request, obstacles: {...o, shadows: true}});
    if (o) return placePreparedFan({...request, obstacles: undefined});
    // Never fails: stack the units in one column to the right.
    const hx = hxMax, hy = hyMax;
    const placements: FanPlacement[] = [];
    let y = -hy;
    for (const unit of units) {
      const shape = request.shape(unit, 0);
      placements.push({card: unit, side: 0, x: hx + shape.extents.left, y: y + shape.extents.top, shape});
      y += shape.extents.top + shape.extents.bottom + spacing.clearY;
    }
    return {placements, extents: fanExtents(request, placements), inner: {hx, hy}};
  }
  return {placements: best.placements, extents: best.extents, inner: {hx: best.hx, hy: best.hy}, ring: true};
}

/**
 * A small fan of leaves on an ellipse around the anchor: evenly round it for a root, or within an arc of up to 200°
 * centred on `direction`, the ellipse grown until every card keeps its clearance from the anchor, the others and the
 * obstacles. Null when the fan is not small or holds more than leaves.
 */
function ellipseFan(request: FanSearch): Fan | null {
  const {units, shape, spacing, obstacles, obstacleGeometry} = request;
  if (!units.length || units.length > ELLIPSE_FAN_MAX) return null;
  const shapes = units.map(unit => shape(unit, 0));
  if (shapes.some(unit => [...unit.offsets.keys()].filter(key => key >= 0).length > 1)) return null;
  const k = units.length;
  const facing = request.direction ?? [0, Math.PI / 2, Math.PI, -Math.PI / 2][request.facing ?? 0];
  let angles: number[];
  if (request.spread) angles = units.map((_, i) => -Math.PI / 2 + (i + 0.5) * 2 * Math.PI / k + (k === 2 ? Math.PI / 2 : 0));
  else {
    const span = k === 1 ? 0 : Math.min(ELLIPSE_FACING_SPAN, (k - 1) * (k <= 2 ? 0.9 : 0.62));
    angles = units.map((_, i) => facing - span / 2 + (k === 1 ? 0 : i * span / (k - 1)));
  }
  const halfWidth = Math.max(...shapes.map(unit => unit.extents.left)), halfHeight = Math.max(...shapes.map(unit => unit.extents.top));
  const a0 = request.halfWidth + spacing.edgeLength + halfWidth;
  const b0 = Math.max(request.halfHeight + spacing.edgeLength + halfHeight, a0 / ELLIPSE_RATIO);
  const anchor = {left: -request.halfWidth, right: request.halfWidth, top: -request.halfHeight, bottom: request.halfHeight};
  // Beside other cards an ellipse that must grow a lot is a poor fit: the ring walk slides units past obstacles instead.
  const limit = obstacles ? ELLIPSE_OBSTACLE_GROWTH : 12;
  for (let scale = 1; scale < limit; scale *= 1.06) {
    const placements = units.map((unit, i): FanPlacement => {
      // The point of the ellipse in direction angles[i] (not its parameter), so the leaves are evenly spread by angle.
      const a = a0 * scale, b = b0 * scale, cos = Math.cos(angles[i]), sin = Math.sin(angles[i]);
      const r = (a * b) / Math.sqrt((b * cos) ** 2 + (a * sin) ** 2);
      const x = cos * r, y = sin * r;
      const side: Side = Math.abs(x) / a0 >= Math.abs(y) / b0 ? (x >= 0 ? 0 : 2) : (y >= 0 ? 1 : 3);
      return {card: unit, side, x, y, shape: shapes[i]};
    });
    const boxes = placements.map(p => absolute(p, p.shape.extents));
    let clear = boxes.every(box => !boxesTouch(box, anchor, spacing.clearX, spacing.clearY));
    for (let i = 0; clear && i < boxes.length; i++) for (let j = i + 1; clear && j < boxes.length; j++) {
      if (boxesTouch(boxes[i], boxes[j], spacing.clearX - 0.01, spacing.clearY - 0.01)) clear = false;
    }
    if (clear && obstacles) {
      clear = placements.every(p => !blocked(p, p.side, p.shape, obstacles, spacing, obstacleGeometry));
    }
    if (!clear) continue;
    let left = request.halfWidth, right = request.halfWidth, top = request.halfHeight, bottom = request.halfHeight;
    for (const box of boxes) { left = Math.max(left, -box.left); right = Math.max(right, box.right); top = Math.max(top, -box.top); bottom = Math.max(bottom, box.bottom); }
    return {placements, extents: {left, right, top, bottom}, inner: {hx: a0 * scale, hy: b0 * scale}};
  }
  return null;
}

/**
 * A big fan of leaves on concentric rectangular rings around the anchor, filled from the inside. One ring's area grows
 * with the square of its units (and its best score then is a ring one card wide and very tall); rings filled in turn
 * grow with their number. The inner ring is where a single ring would start, each next one a card and a clearance
 * further out, with the steps stretched so the outermost ring approaches the wanted aspect ratio. Alternate rings are
 * shifted by half a slot, so an arrow to an outer card tends to pass between the cards of the rings inside. A facing
 * fan uses only the slots within its span; slots an obstacle blocks are skipped. Null when the fan is small, holds more
 * than leaves, or (with obstacles) finds no room.
 */
function ringsFan(request: FanSearch): Fan | null {
  const {units, shape, spacing, obstacles, obstacleGeometry} = request;
  if (units.length < RINGS_FAN_MIN) return null;
  const shapes = units.map(unit => shape(unit, 0));
  if (shapes.some(unit => [...unit.offsets.keys()].filter(key => key >= 0).length > 1)) return null;
  const width = Math.max(...shapes.map(unit => unit.extents.left + unit.extents.right));
  const height = Math.max(...shapes.map(unit => unit.extents.top + unit.extents.bottom));
  // Twice the clearance between the cards of a side: room for the arrows to the rings outside.
  const pitchX = width + spacing.clearX * 2, pitchY = height + spacing.clearY * 2;
  let stepX = width + spacing.clearX * RING_LANE, stepY = height + spacing.clearY * RING_LANE;
  if (stepX / stepY > spacing.aspectRatio) stepY = stepX / spacing.aspectRatio;
  else stepX = stepY * spacing.aspectRatio;
  const facing = request.direction ?? [0, Math.PI / 2, Math.PI, -Math.PI / 2][request.facing ?? 0];
  const reach = Math.PI * Math.min(1, request.span ?? 1);
  const within = (x: number, y: number) =>
    request.spread || reach >= Math.PI || Math.abs(Math.atan2(Math.sin(Math.atan2(y, x) - facing), Math.cos(Math.atan2(y, x) - facing))) <= reach;
  // Centres of the cards (of size `card`, every `pitch`) that fit a side of `length`, centred on it; one fewer, half a
  // pitch along, when shifted.
  const along = (length: number, card: number, pitch: number, shifted: boolean) => {
    const count = (length < card ? 0 : Math.floor((length - card) / pitch) + 1) - (shifted ? 1 : 0);
    return Array.from({length: Math.max(0, count)}, (_, j) => (j - (count - 1) / 2) * pitch);
  };
  type Slot = {side: Side; at: number};
  const ringSlots = (hx: number, hy: number, shifted: boolean): Slot[] => {
    // Clockwise from the top of the right side (y down): the sides hold the corners, the top and bottom rows keep a
    // clearance from them.
    const columns = along(2 * (hy + height), height, pitchY, shifted);
    const rows = along(2 * (hx - spacing.clearX), width, pitchX, shifted);
    return [
      ...columns.map(at => ({side: 0 as Side, at})),
      ...[...rows].reverse().map(at => ({side: 1 as Side, at})),
      ...[...columns].reverse().map(at => ({side: 2 as Side, at})),
      ...rows.map(at => ({side: 3 as Side, at})),
    ];
  };
  const centre = (slot: Slot, unit: UnitShape, hx: number, hy: number) => {
    const e = unit.extents;
    switch (slot.side) {
      case 0: return {x: hx + e.left, y: slot.at};
      case 1: return {x: slot.at, y: hy + e.top};
      case 2: return {x: -hx - e.right, y: slot.at};
      default: return {x: slot.at, y: -hy - e.bottom};
    }
  };
  const placements: FanPlacement[] = [];
  let hx = request.halfWidth + spacing.edgeLength, hy = request.halfHeight + spacing.edgeLength * 0.7;
  let outer = {hx, hy};
  for (let ring = 0; placements.length < units.length && ring < RINGS_MAX; ring++, hx += stepX, hy += stepY) {
    const next = placements.length;
    const free = ringSlots(hx, hy, ring % 2 === 1).filter(slot => {
      const at = centre(slot, shapes[next], hx, hy);
      return within(at.x, at.y) &&
        !(obstacles && blocked(at, slot.side, shapes[next], obstacles, spacing, obstacleGeometry));
    });
    if (!free.length) continue;
    const remaining = units.length - next;
    // The last ring spreads what is left evenly round its free slots.
    const chosen = remaining >= free.length ? free : Array.from({length: remaining}, (_, i) => free[Math.floor((i + 0.5) * free.length / remaining)]);
    chosen.forEach((slot, i) => {
      const unit = shapes[next + i];
      placements.push({card: units[next + i], side: slot.side, ...centre(slot, unit, hx, hy), shape: shape(units[next + i], slot.side)});
    });
    outer = {hx, hy};
  }
  if (placements.length < units.length) return null;
  return {placements, extents: fanExtents(request, placements), inner: outer, ring: true};
}

/** Packs or spreads the units on the ring of half size (hx, hy); null when they do not fit. */
function arrange(request: FanSearch, hx: number, hy: number, span: number): FanPlacement[] | null {
  const perimeter = 4 * hx + 4 * hy;
  const limit = perimeter * Math.min(1, span);
  if (request.spread) {
    const packed = walk(request, hx, hy, 0, limit, 1);
    if (!packed) return null;
    // Spread: the largest gap scale that still fits, so a root's children go all the way round.
    let low = 1, high = 1 + perimeter / Math.max(1, request.units.length * Math.min(request.spacing.clearX, request.spacing.clearY)), best = packed;
    for (let iteration = 0; iteration < 12; iteration++) {
      const middle = (low + high) / 2, placed = walk(request, hx, hy, 0, limit, middle);
      if (placed) { low = middle; best = placed; } else high = middle;
    }
    return best;
  }
  const facing = request.facing ?? 0;
  const middle = sideStart(facing, hx, hy) + sideLength(facing, hx, hy) / 2;
  const start = middle - limit / 2;
  const packed = walk(request, hx, hy, start, limit, 1);
  if (!packed) return null;
  // Centre the packed run on the facing side: start later by half the unused part of the allowed span.
  const used = runLength(packed, hx, hy, start);
  const shifted = walk(request, hx, hy, start + Math.max(0, (limit - used) / 2), limit - Math.max(0, (limit - used) / 2), 1);
  return shifted ?? packed;
}

/** Perimeter length from `start` to the end of the last placed unit. */
function runLength(placements: FanPlacement[], hx: number, hy: number, start: number) {
  const last = placements[placements.length - 1];
  const perimeter = 4 * hx + 4 * hy;
  const e = last.shape.extents;
  let s: number;
  switch (last.side) {
    case 0: s = last.y - e.top + hy; break;
    case 1: s = hx - last.x - e.right; break;
    case 2: s = hy - last.y - e.bottom; break;
    default: s = last.x - e.left + hx;
  }
  const t = sideStart(last.side, hx, hy) + s + alongExtent(last.side, e);
  return ((t - start) % perimeter + perimeter) % perimeter;
}

/**
 * Shapes of every pendant unit, bottom-up and memoised per outward side. `children` lists each card's pendant
 * children in drawing order; `size` gives card sizes.
 */
export function unitShapes(children: readonly (readonly number[])[], size: (card: number) => {width: number; height: number},
  spacing: FanSpacing) {
  const memo = new Map<number, UnitShape>();
  const shape = (card: number, side: Side): UnitShape => {
    const key = card * 4 + side, known = memo.get(key);
    if (known) return known;
    const {width, height} = size(card);
    const own = {left: width / 2, right: width / 2, top: height / 2, bottom: height / 2};
    let result: UnitShape;
    if (!children[card].length) {
      result = {extents: own, offsets: new Map([[card, {x: 0, y: 0}], [-1, {x: width / 2, y: height / 2}]])};
    } else {
      const fan = placeFan({halfWidth: width / 2, halfHeight: height / 2, units: [...children[card]], shape,
        spacing: {...spacing, aspectRatio: side % 2 === 0 ? 2.5 : 0.9}, facing: side, span: 0.5});
      const offsets = new Map<number, {x: number; y: number}>([[card, {x: 0, y: 0}], [-1, {x: width / 2, y: height / 2}]]);
      for (const p of fan.placements) for (const [id, o] of p.shape.offsets) if (id >= 0) offsets.set(id, {x: p.x + o.x, y: p.y + o.y});
      result = {extents: fan.extents, offsets};
    }
    memo.set(key, result);
    return result;
  };
  return shape;
}
